cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables);
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n--- ' + t.name + ' ---');
  console.log('Columns:', cols.map(c => c.name));
  const rows = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 3').all();
  rows.forEach(r => console.log(r));
}
db.close();
" 2>/dev/null || echo "better-sqlite3 not available"

cd /workspace && NODE_PATH=/tmp/sqlitemod/node_modules node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Check schema
const cols = db.prepare('PRAGMA table_info(products)').all();
console.log('Columns:', cols.map(c => c.name).join(', '));

// Count products
const count = db.prepare('SELECT COUNT(*) as cnt FROM products').get();
console.log('Total products:', count.cnt);

// Look for Bluetooth speakers
const rows = db.prepare(\"SELECT * FROM products WHERE LOWER(name) LIKE '%bluetooth%' OR LOWER(name) LIKE '%speaker%' OR LOWER(subcategory) LIKE '%speaker%' OR LOWER(category) LIKE '%speaker%'\").all();
console.log('\n=== Bluetooth/Speaker Products ===');
console.log('Found:', rows.length);
rows.forEach(r => console.log(JSON.stringify(r, null, 2)));
db.close();
"

cd /workspace && NODE_PATH=/tmp/sqlitemod/node_modules node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Get compatible products for the Anker speaker
const compatIds = ['PROD-FA0948','PROD-2DBA15','PROD-7C0240','PROD-73FAB4'];
const placeholders = compatIds.map(() => '?').join(',');
const compat = db.prepare('SELECT product_id, name, brand, category, subcategory, price, rating, review_count, description, in_stock FROM products WHERE product_id IN (' + placeholders + ')').all(...compatIds);
console.log('=== Compatible Products ===');
compat.forEach(r => console.log(JSON.stringify(r)));

// Also get other audio/portable electronics
console.log('\n=== Other Audio/Electronics Products ===');
const audio = db.prepare(\"SELECT product_id, name, brand, category, subcategory, price, rating, review_count, description, in_stock FROM products WHERE (LOWER(subcategory) LIKE '%audio%' OR LOWER(category) = 'electronics') AND product_id != 'PROD-B98D14'\").all();
audio.forEach(r => console.log(JSON.stringify(r)));
db.close();
"

